function StoreScreen({ route, navigation }) {
  const { slug } = route.params; const [store, setStore] = useState(null); const [products, setProducts] = useState([]); const [error, setError] = useState('');
  useEffect(() => { api.get(`/stores/${slug}`).then(({ data }) => { setStore(data.store); setProducts(data.products || []); }).catch((e) => setError(e.response?.data?.message || 'Could not load this store.')); }, [slug]);
  const themeColor = ({ ocean: '#2451c5', violet: '#6b4bc3', forest: '#28744e' })[store?.theme] || '#2451c5';
  return <View style={styles.screen}><Header navigation={navigation} title={store?.name || 'Store'} />{error ? <Text style={styles.authError}>{error}</Text> : <FlatList data={products} numColumns={2} keyExtractor={(item) => String(item._id)} contentContainerStyle={styles.gridList} columnWrapperStyle={{ gap: 12 }} ListHeaderComponent={store ? <View style={[styles.panel, { backgroundColor: themeColor }]}><Text style={{ color: '#dce8ff', fontSize: 11, fontWeight: '800', letterSpacing: 1 }}>INDEPENDENT SHOP</Text><Text style={[styles.detailTitle, { color: '#fff', marginVertical: 5 }]}>{store.name}</Text><Text style={{ color: '#e5edff', fontSize: 12 }}>Prices in PKR · {products.length} products</Text></View> : null} renderItem={({ item }) => <View style={{ flex: 1 }}><ProductCard item={item} navigation={navigation} /></View>} ListEmptyComponent={<Text style={styles.empty}>{store ? 'This store has no products yet.' : 'Loading store…'}</Text>} />}</View>;
}
function Quantity({ value, onChange, compact, max = 99 }) { return <View style={[styles.quantity, compact && styles.quantityCompact]}><Pressable onPress={() => onChange(Math.max(1, value - 1))}><Text style={styles.qtyButton}>−</Text></Pressable><Text style={styles.qtyNumber}>{value}</Text><Pressable onPress={() => onChange(Math.min(max, value + 1))} disabled={value >= max}><Text style={[styles.qtyButton, value >= max && styles.muted]}>＋</Text></Pressable></View>; }
function CartScreen({ navigation }) {
  const { cart, saveCart } = useShop();
  const insets = useSafeAreaInsets();
  const subtotal = cart.reduce((sum, row) => sum + row.product.price * row.quantity, 0);
  const change = (id, variant, quantity) => saveCart(cart.map((row) => row.product._id === id && row.variant === variant ? { ...row, quantity } : row).filter((row) => row.quantity > 0));
  return <View style={styles.screen}><Header navigation={navigation} title="Your bag" />{cart.length ? <><FlatList data={cart} keyExtractor={(row) => `${row.product._id}-${row.variant || 'default'}`} contentContainerStyle={{ padding: 18 }} renderItem={({ item }) => <View style={styles.cartRow}><Image source={{ uri: fullImage(item.product.image) }} style={styles.cartImage} /><View style={{ flex: 1 }}><Text style={styles.productName}>{item.product.name}</Text>{item.variant ? <Text style={styles.muted}>Options: {item.variant}</Text> : null}<Text style={styles.productPrice}>{money(item.product.price)}</Text><Quantity compact max={Math.max(item.quantity, Math.min(99, item.product.stock || 1))} value={item.quantity} onChange={(quantity) => change(item.product._id, item.variant, quantity)} /></View><Pressable onPress={() => change(item.product._id, item.variant, 0)}><Ionicons name="trash-outline" size={20} color="#8a95a5" /></Pressable></View>} /><View style={[styles.checkoutSummary, { paddingBottom: Math.max(insets.bottom, 14) }]}><SummaryRow label="Subtotal" value={money(subtotal)} /><SummaryRow label="Shipping fee" value={money(250)} /><SummaryRow label="Total" value={money(subtotal + 250)} strong /><Pressable onPress={() => navigation.navigate('Checkout')} style={[styles.primaryButton, { flexDirection: 'row', gap: 8 }]}><Text style={styles.primaryText}>Continue to checkout</Text><Ionicons name="arrow-forward-circle-outline" size={19} color="#fff" /></Pressable></View></> : <EmptyState icon="bag-outline" title="Your bag is waiting" subtitle="Add something you love and it will appear here." action="Explore products" onPress={() => navigation.navigate('Shop')} />}</View>;
}
function SummaryRow({ label, value, strong }) { return <View style={styles.summaryRow}><Text style={strong ? styles.summaryStrong : styles.summaryLabel}>{label}</Text><Text style={strong ? styles.summaryStrong : styles.summaryValue}>{value}</Text></View>; }
function PaymentReferenceForm({ order }) {
  const [methods, setMethods] = useState([]); const [reference, setReference] = useState(order.paymentReference || '');
  const [status, setStatus] = useState(order.paymentStatus); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  useEffect(() => { api.get('/payment-methods').then(({ data }) => setMethods(data.methods || [])).catch(() => {}); }, []);
  if (!order || order.paymentMethod === 'COD' || order.paymentMethod === 'DEMO_CARD') return null;
  const method = methods.find((item) => item.id === order.paymentMethod);
  const submit = async () => { setBusy(true); setError(''); try { const { data } = await api.post(`/orders/${order._id}/payment-reference`, { reference }); setStatus(data.order.paymentStatus); } catch (e) { setError(e.response?.data?.message || 'Could not submit payment reference.'); } finally { setBusy(false); } };
  return <View style={styles.panel}><Text style={styles.panelTitle}>{status === 'pending_verification' ? 'Payment submitted' : status === 'paid' ? 'Payment verified' : 'Complete your transfer'}</Text>{method ? <Text style={styles.description}>{[method.bank, method.accountName, method.account, method.instructions].filter(Boolean).join('\n')}</Text> : <Text style={styles.authError}>Payment details are not available. Contact the store before transferring.</Text>}{status === 'pending_verification' ? <Text style={[styles.successNotice, { marginTop: 10 }]}>Reference submitted. The admin will verify the transfer and update your order.</Text> : status === 'paid' ? <Text style={styles.successNotice}>Your payment has been verified.</Text> : <><Text style={styles.inputLabel}>Transaction reference</Text><TextInput value={reference} onChangeText={setReference} placeholder="Enter the bank or wallet transaction ID" autoCapitalize="characters" style={styles.authInput} /><Pressable onPress={submit} disabled={busy || reference.trim().length < 4} style={[styles.primaryButton, (busy || reference.trim().length < 4) && { opacity: 0.55 }]}><Text style={styles.primaryText}>{busy ? 'Submitting…' : 'Submit payment reference'}</Text></Pressable>{error ? <Text style={styles.authError}>{error}</Text> : null}</>}</View>;
}
