  const update=(key,value)=>setForm((current)=>({...current,[key]:value}));
  const load=useCallback(async()=>{if(!token)return;try{const {data}=await api.get('/addresses');const saved=data.addresses||[];setAddresses(saved);const id=route.params?.editAddressId;const selected=id&&saved.find((a)=>a._id===id);if(selected){setEditingId(selected._id);const savedPhone=splitSavedPhone(selected.phone,selected.phoneCountryCode||selected.countryCode||'PK');setForm({...blankForm(),...selected,phone:savedPhone.phone,phoneCountryCode:selected.phoneCountryCode||savedPhone.code,country:selected.country||'Pakistan',countryCode:selected.countryCode||'PK',province:selected.province||''});navigation.setParams({editAddressId:undefined});}}catch(e){setError(e.response?.data?.message||'Could not load addresses.');}},[token,route.params?.editAddressId,navigation]);
  useFocusEffect(useCallback(()=>{load();},[load]));
