  useFocusEffect(useCallback(() => { load(); }, [load]));
  const visible = filter === 'all' ? orders : orders.filter((order) => order.status === filter);
  if (!user) return <View style={styles.screen}><Header navigation={navigation} title="My orders" icon="receipt-outline" /><EmptyState icon="cube-outline" title="Sign in to see your orders" subtitle="Your order history and delivery updates are saved to your account." action="Sign in" onPress={() => navigation.navigate('Auth')} /></View>;
  return <View style={styles.screen}><Header navigation={navigation} title="My orders" icon="receipt-outline" /><ScrollView horizontal showsHorizontalScrollIndicator={false} style={{ flexGrow: 0 }} contentContainerStyle={styles.chips}>{ORDER_STATUSES.map((status) => <Pressable key={status} onPress={() => setFilter(status)} style={[styles.chip, filter === status && styles.chipActive]}><Text style={[styles.chipText, filter === status && { color: '#fff' }]}>{status === 'all' ? 'All' : statusLabel(status)}</Text></Pressable>)}</ScrollView>{error ? <Text style={styles.authError}>{error}</Text> : null}<FlatList data={visible} keyExtractor={(order) => order._id} contentContainerStyle={styles.gridList} renderItem={({ item }) => <Pressable style={styles.orderCard} onPress={() => navigation.navigate('OrderDetails', { orderId: item._id })}><View style={styles.orderTop}><Text style={styles.productName}>Order #{String(item._id).slice(-8)}</Text><Text style={styles.statusBadge}>{statusLabel(item.status)}</Text></View><Text style={styles.description}>{new Date(item.createdAt).toLocaleDateString()} · {item.items.length} item{item.items.length === 1 ? '' : 's'}</Text><View style={styles.summaryRow}><Text style={styles.summaryLabel}>{item.items.map((row) => row.name).join(', ')}</Text><Text style={styles.summaryStrong}>{money(item.total)}</Text></View><Text style={styles.link}>View order  ›</Text></Pressable>} ListEmptyComponent={<Text style={styles.empty}>{error ? '' : 'No orders in this section yet.'}</Text>} />
  </View>;
