function RootTabs() { const { themeColor, appearanceColors } = useShop(); const insets = useSafeAreaInsets(); const bottomInset = Math.max(insets.bottom, 8); return <Tabs.Navigator screenOptions={({ route }) => ({ headerShown: false, tabBarHideOnKeyboard: true, tabBarActiveTintColor: themeColor, tabBarInactiveTintColor: '#96a2b2', tabBarLabelStyle: { fontSize: 11, fontWeight: '600', marginBottom: 3 }, tabBarStyle: { height: 62 + bottomInset, paddingTop: 7, paddingBottom: bottomInset, borderTopColor: appearanceColors.border, backgroundColor: appearanceColors.surface }, tabBarIcon: ({ color, size }) => { const icons = { Home: 'home-outline', Shop: 'grid-outline', Wishlist: 'heart-outline', Orders: 'cube-outline', Profile: 'person-outline' }; return <Ionicons name={icons[route.name]} size={size} color={color} />; } })}><Tabs.Screen name="Home" component={HomeScreen} /><Tabs.Screen name="Shop" component={ShopScreen} /><Tabs.Screen name="Wishlist" component={WishlistScreen} options={{ tabBarBadge: undefined }} /><Tabs.Screen name="Orders" component={OrdersScreen} /><Tabs.Screen name="Profile" component={ProfileScreen} /></Tabs.Navigator>; }
function SplashScreen() { const { appearanceColors } = useShop(); return <View style={styles.splash}><StatusBar style={appearanceColors.statusBarStyle} /><View style={styles.splashLogo}><Ionicons name="bag-handle" size={54} color="#fff" /></View><Text style={styles.splashTitle}>ShopNexa</Text><Text style={styles.splashSubtitle}>Find your everyday favourites.</Text></View>; }
function OnboardingScreen({ navigation }) {
  const { appearanceColors } = useShop();
  const slides = [
    { icon: 'bag-handle-outline', title: 'A better way to shop', body: 'Explore useful finds from fashion and accessories to everyday essentials.' },
    { icon: 'cube-outline', title: 'Follow every order', body: 'Save delivery addresses and see each update as your order moves along.' },
    { icon: 'trending-up-outline', title: 'Share and resell', body: 'Set your customer price and see potential profit after delivery and settlement.' }
  ];
  const [index, setIndex] = useState(0); const slide = slides[index];
  const finish = async () => { await AsyncStorage.setItem('shopnexa.onboardingDone', 'true'); navigation.replace('Main'); };
  return <View style={styles.onboarding}><StatusBar style={appearanceColors.statusBarStyle} /><Pressable onPress={finish} style={styles.skip}><Text style={styles.link}>Skip</Text></Pressable><View style={styles.onboardingArt}><View style={styles.onboardingCircle}><Ionicons name={slide.icon} size={58} color={BLUE} /></View><View style={styles.onboardingSparkle}>✦</View></View><Text style={styles.onboardingTitle}>{slide.title}</Text><Text style={styles.onboardingBody}>{slide.body}</Text><View style={styles.onboardingDots}>{slides.map((item, i) => <View key={item.title} style={[styles.onboardingDot, i === index && styles.onboardingDotActive]} />)}</View><View style={styles.onboardingActions}>{index > 0 ? <Pressable onPress={() => setIndex(index - 1)} style={styles.secondaryButton}><Text style={styles.authSwitchText}>Back</Text></Pressable> : <View style={styles.secondarySpacer} />}<Pressable onPress={() => index === slides.length - 1 ? finish() : setIndex(index + 1)} style={[styles.primaryButton, { flex: 1 }]}><Text style={styles.primaryText}>{index === slides.length - 1 ? 'Get started' : 'Continue'}</Text></Pressable></View></View>;
}
function AppNavigator() {
  const [showOnboarding, setShowOnboarding] = useState(null);
  const { openDrawerFromGesture, appearanceColors, themeColor } = useShop(); const { width } = useWindowDimensions();
  const edgeSwipe = useRef(PanResponder.create({
    onStartShouldSetPanResponderCapture: () => false,
    onMoveShouldSetPanResponderCapture: (_event, gesture) => gesture.x0 >= width - 32 && gesture.dx < -12 && Math.abs(gesture.dx) > Math.abs(gesture.dy) * 1.15,
    onPanResponderGrant: openDrawerFromGesture,
    onPanResponderTerminationRequest: () => false
  })).current;
  useEffect(() => { AsyncStorage.getItem('shopnexa.onboardingDone').then((value) => setShowOnboarding(value !== 'true')).catch(() => setShowOnboarding(true)); }, []);
  if (showOnboarding === null) return <SplashScreen />;
  return <View style={{ flex: 1 }} {...edgeSwipe.panHandlers}><KeyboardAvoidingView style={{ flex: 1 }} behavior={Platform.OS === 'ios' ? 'padding' : 'height'}><NavigationContainer><Stack.Navigator initialRouteName={showOnboarding ? 'Onboarding' : 'Main'} screenOptions={{ headerShown: false }}><Stack.Screen name="Onboarding" component={OnboardingScreen} /><Stack.Screen name="Main" component={RootTabs} /><Stack.Screen name="Product" component={ProductScreen} /><Stack.Screen name="Store" component={StoreScreen} /><Stack.Screen name="Cart" component={CartScreen} /><Stack.Screen name="Checkout" component={CheckoutScreen} /><Stack.Screen name="Auth" component={AuthScreen} /><Stack.Screen name="Admin">{(props) => <AdminScreen {...props} appearanceColors={appearanceColors} themeColor={themeColor} />}</Stack.Screen><Stack.Screen name="Addresses" component={AddressScreen} /><Stack.Screen name="OrderDetails" component={OrderDetailsScreen} /><Stack.Screen name="Notifications" component={NotificationsScreen} /><Stack.Screen name="Review" component={ReviewScreen} /><Stack.Screen name="Reseller" component={ResellerScreen} /><Stack.Screen name="Seller" component={SellerScreen} /><Stack.Screen name="Support" component={SupportScreen} /><Stack.Screen name="ProfileEdit" component={ProfileEditScreen} /><Stack.Screen name="Wallets" component={WalletsScreen} /></Stack.Navigator></NavigationContainer></KeyboardAvoidingView></View>;
}
export default function App() { return <SafeAreaProvider><ShopProvider><AppNavigator /></ShopProvider></SafeAreaProvider>; }

